  if exists(select 1 from public.webbase_products where id=(r->>'id')::uuid and sku is distinct from r->>'sku') then raise exception 'Conflicting product identity'; end if;
  if not exists(select 1 from public.webbase_products where id=(r->>'id')::uuid) then
   if exists(select 1 from public.webbase_products where private.webbase_sku_keys(sku,source_skus) && private.webbase_sku_keys(r->>'sku',array[r->>'sku'])) then raise exception 'SKU already belongs to another product: %',r->>'sku'; end if;
   insert into public.webbase_products(id,external_id,sku,name,category,model,memory,color,brand,description,specs,source_name,source_skus,active)
   values((r->>'id')::uuid,r->>'external_id',r->>'sku',r->>'name',r->>'category',nullif(r->>'model',''),nullif(r->>'memory',''),nullif(r->>'color',''),nullif(r->>'brand',''),r->>'description',r->'specs',r->>'source_name',array[r->>'sku'],true);
  end if;
  insert into public.webbase_stock(product_id,warehouse,display,ldu) values((r->>'id')::uuid,0,0,0) on conflict(product_id) do nothing;
  for i in select value from jsonb_array_elements(r->'images') loop
   if not exists(select 1 from storage.objects where bucket_id='webbase-products' and name=i->>'storage_path' and (metadata->>'size')::integer=(i->>'byte_size')::integer) then raise exception 'Verified storage file missing: %',i->>'storage_path'; end if;
   insert into public.webbase_product_images(id,product_id,storage_path,sort_order,is_primary,mime_type,byte_size,width,height,original_name,source_url)
   values((i->>'id')::uuid,(r->>'id')::uuid,i->>'storage_path',(i->>'sort_order')::integer,(i->>'is_primary')::boolean,'image/webp',(i->>'byte_size')::integer,640,640,i->>'original_name',i->>'source_url') on conflict(storage_path) do nothing;
  end loop;
