begin
 for r in select value from jsonb_array_elements('[{"id":"71f91fed-c3cf-51c2-ba98-257d5fc8dc31","sku":"6932554458126","name":"Беспроводные наушники REDMI Buds 8 Pro белый","brand":"REDMI","model":"M2535E1","memory":"","category":"Наушники","color":"белый","external_id":"mi-shop:6932554458126","source_name":"Беспроводные наушники REDMI Buds 8 Pro белый","source_skus":["6932554458126"],"description":"REDMI Buds 8 Pro — флагманские полностью беспроводные наушники, созданные для пользователей, которые ценят высокое качество звука, эффективное шумоподавление и современные интеллектуальные функции. Благодаря внутриканальной конструкции и нескольким комплектам амбушюр наушники обеспечивают надежную посадку и комфорт даже при длительном использовании.\n\nЗа впечатляющее звучание отвечает коаксиальная трёхдрайверная акустическая система нового поколения, включающая 11-мм динамический драйвер с титановым покрытием и два пьезокерамических излучателя. Такая конструкция позволяет добиться глубоких басов, детализированных средних частот и кристально чистых высоких нот. Наушники поддерживают Hi-Res Audio Wireless, кодек LHDC 5.0 и технологию Dolby Audio, обеспечивая объёмное и насыщенное звучание при прослушивании музыки, просмотре фильмов и во время игр.\n\nСистема активного шумоподавления нового поколения способна снижать уровень внешнего шума до 55 дБ в диапазоне до 5 кГц. Интеллектуальные алгоритмы автоматически адаптируют работу ANC к окружающей обстановке, помогая сосредоточиться на музыке или разговоре даже в шумных местах. Три микрофона с AI-шумоподавлением обеспечивают высокое качество голосовой связи и эффективно подавляют шум ветра на скорости до 12 м/с.\n\nПоддержка пространственного звучания с отслеживанием положения головы делает прослушивание более реалистичным и позволяет глубже погрузиться в контент. Bluetooth 5.4 обеспечивает быстрое подключение, стабильную связь и минимальные задержки при использовании со смартфонами, планшетами и ноутбуками.\n\nЗарядный кейс отличается компактными размерами и оснащён светодиодной индикацией уровня заряда. Ёмкий аккумулятор позволяет использовать наушники в течение всего дня, а современный разъём USB Type-C обеспечивает удобную и быструю зарядку.","specs":{"Bluetooth":"5.4","Емкость аккумулятора, мА*ч":"Наушники: 54 мАч; Зарядный чехол: 480 мАч","Время работы, ч":"до 33 часов с футляром","Тип разъема для зарядки":"USB Type-C","Напряжение, В":"5","Сменные амбушюры":"Да","Количество пар сменных амбушюр в комплекте":"2","Гарантия, мес":"12","Технология":"динамические","Конструкция наушников":"вставные (затычки)","Сопротивление, Ом":"32 Ом","Страна производитель":"Китай","Микрофон":"Да","Модель":"M2535E1","Совместимые ОС":"Android, iOS","Тип подключения":"Bluetooth","Чувствительность, дБ":"55","Степень защиты":"IP54","Высота, мм":"61,01","Материал":"Пластик","Толщина, мм":"25,17","Вес, г":"46.9","Ширина, мм":"48,28","_source_url":"https://mi-shop.com/catalog/audio/redmi-buds-8-pro-belyy/","_verified_at":"2026-10-25","_catalog_source":"mi-shop.com","_catalog_source_sku":"6932554458126","_catalog_source_id":"16343","_catalog_availability":"InStock","_catalog_unavailable_exception":false,"_description_kind":"source_overview"},"active":true,"images":[{"id":"ba94649d-3c3b-5496-a2cd-514f99c4df37","product_id":"71f91fed-c3cf-51c2-ba98-257d5fc8dc31","sku":"6932554458126","storage_path":"products/71f91fed-c3cf-51c2-ba98-257d5fc8dc31/ba94649d-3c3b-5496-a2cd-514f99c4df37.webp","sort_order":0,"is_primary":true,"mime_type":"image/webp","byte_size":5462,"width":640,"height":640,"sha256":"440d7eaf40ad5c25e96a2a056d22a8c94adab66ccf06c6c5573542213943829e","source_url":"https://mi-shop.com/catalog/audio/redmi-buds-8-pro-belyy/","image_url":"https://mi-shop.com/upload/iblock/d9a/77uhcvggy4lm2bv13km849sg4wh9agku.png","original_name":"Беспроводные наушники REDMI Buds 8 Pro белый — 1"}]},{"id":"83df8274-85b2-5fb0-96a0-c5f503e4b649","sku":"6932554458171","name":"Беспроводные наушники REDMI Buds 8 Pro черный","brand"