   insert into public.webbase_product_images(id,product_id,storage_path,sort_order,is_primary,mime_type,byte_size,width,height,original_name,source_url)
   values((i->>'id')::uuid,(r->>'id')::uuid,i->>'storage_path',(i->>'sort_order')::integer,(i->>'is_primary')::boolean,'image/webp',(i->>'byte_size')::integer,640,640,i->>'original_name',i->>'source_url') on conflict(storage_path) do nothing;
  end loop;
